const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Namibia geometry
  const namibia = ee.FeatureCollection('FAO/administrative_boundaries_open/1.0/countries')
    .filter(ee.Filter.eq('ADM0_NAME', 'Namibia'));

  const namibiaGeom = namibia.geometry();

  // 2. Acquire CHIRPS precipitation data for January 2021
  const startDate = '2021-01-01';
  const endDate = '2021-01-31';

  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/MONTHLY')
    .filterDate(startDate, endDate)
    .filterBounds(namibiaGeom);

  const size = chirps.size().getInfo();
  console.log(`CHIRPS Images in Jan 2021: ${size}`);

  if (size === 0) {
    console.log('No CHIRPS data found for January 2021 over Namibia.');
    console.log('C1');
    return;
  }

  // 3. Get the precipitation image for January 2021
  const precip = chirps.first();

  // 4. Calculate mean rainfall over Namibia
  const precipStats = precip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: namibiaGeom,
    scale: 5000,
    maxPixels: 1e9
  });

  const meanRainfall = precipStats.get('precipitation').getInfo();

  console.log(`Mean Rainfall in Jan 2021: ${meanRainfall} mm`);

  // Check for valid pixel count
  const pixelCount = precip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: namibiaGeom,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid Pixels: ${pixelCount}`);

  // 5. Validation & Answer
  if (meanRainfall === null || isNaN(meanRainfall)) {
    console.log('C3');
    return;
  }

  if (pixelCount === 0) {
    console.log('C2');
    return;
  }

  const sevenInchesInMm = 7 * 25.4; // 177.8 mm

  if (meanRainfall > sevenInchesInMm) {
    console.log(`Over 7 inches (${sevenInchesInMm.toFixed(1)} mm): Yes (${meanRainfall.toFixed(1)} mm)`);
    console.log('A');
  } else {
    console.log(`Over 7 inches (${sevenInchesInMm.toFixed(1)} mm): No (${meanRainfall.toFixed(1)} mm)`);
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
